17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.samples.petclinic.util.AddressNormalizer;
46	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
47	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Maximum number of owners a single city may contain; creating an owner in a city that
66	     *  already has this many owners is rejected with 409 Conflict. */
67	    private static final int MAX_OWNERS_PER_CITY = 50;
68	
69	    /** Maximum number of owners that may be created on a single day (by registration date); creating
70	     *  an owner once this many owners already carry today's registration date is rejected with
71	     *  429 Too Many Requests. */
72	    private static final int MAX_OWNERS_PER_DAY = 100;
73	
74	    /** When more than this many owners already carry today's registration date at creation time, the
75	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
76	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
77	
78	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final TelephoneNormalizer telephoneNormalizer;
90	
91	    private final HouseholdNormalizer householdNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 HouseholdNormalizer householdNormalizer,
101	                                 AddressNormalizer addressNormalizer) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.householdNormalizer = householdNormalizer;
108	        this.addressNormalizer = addressNormalizer;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        normalizeOwnerFields(owner);
142	        // Enforce the pre-persistence policies that can reject the new owner outright.
143	        rejectDisallowedOwnerCreation(owner);
144	        // Identify any existing owners who share a household (same last name and address,
145	        // compared case-insensitively with collapsed whitespace) with the owner being created.
146	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
147	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
148	        // Reject creating an owner who shares a household with an existing owner, unless the
149	        // request explicitly opts in with 'sharesHousehold' true.
150	        if (!sharesHousehold && !householdMembers.isEmpty()) {
151	            throw new DuplicateHouseholdException(
152	                "An owner with the same last name and address already exists");
153	        }
154	        // When opting in and joining an existing household, assign the new owner and every
155	        // existing member the same stable household identifier derived from the last name and
156	        // address, so all owners of the household share one 'householdId'.
157	        if (sharesHousehold && !householdMembers.isEmpty()) {
158	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
159	            owner.setHouseholdId(householdId);
160	            for (Owner member : householdMembers) {
161	                if (!householdId.equals(member.getHouseholdId())) {
162	                    member.setHouseholdId(householdId);
163	                    this.clinicService.saveOwner(member);
164	                }
165	            }
166	        }
167	        // Record the size of this owner's household after this create, i.e. the number of owners
168	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
169	        // household counts the matched members plus itself; an owner without a shared household is a
170	        // household of one. Fixed at creation time.
171	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
172	        // Record how many existing owners already share this owner's first and last name
173	        // (compared case-insensitively) before this create, fixed at creation time.
174	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
175	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
176	        // per-city sequence equal to one more than the owners already in that city, fixed at
177	        // creation time.
178	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
179	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
180	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
181	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
182	        // Flag the create when more than 80 owners have already been created on this owner's
183	        // (adjusted business-day) registration date, fixed at creation time.
184	        owner.setBulkSignupWarning(
185	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
186	        this.clinicService.saveOwner(owner);
187	        // Emit an audit line for the successful create, carrying the owner id, customer code and
188	        // registration date so the create can be traced from the dedicated AUDIT log.
189	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
190	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
191	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    /**
198	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
199	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
200	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
201	     * the sequence of create-time rejections stays readable and a new rule is added as one more
202	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
203	     * and persistence steps. The household rule stays in {@link #addOwner} itself because it shares
204	     * the matched-member lookup with the shared household-id assignment.
205	     *
206	     * @param owner the newly mapped and normalized owner being created
207	     */
208	    private void rejectDisallowedOwnerCreation(Owner owner) {
209	        rejectWhenDailyLimitReached(owner);
210	        rejectWhenCityAtCapacity(owner);
211	        rejectWhenTelephoneInUse(owner);
212	    }
213	
214	    /**
215	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
216	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
217	     *
218	     * @param owner the owner being created
219	     */
220	    private void rejectWhenDailyLimitReached(Owner owner) {
221	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
222	            throw new DailyOwnerLimitExceededException(
223	                "The maximum number of owners that may be created today has already been reached");
224	        }
225	    }
226	
227	    /**
228	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
229	     * or more owners, with 409 Conflict.
230	     *
231	     * @param owner the owner being created
232	     */
233	    private void rejectWhenCityAtCapacity(Owner owner) {
234	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
235	            throw new CityCapacityExceededException(
236	                "The city " + owner.getCity() + " already contains the maximum number of owners");
237	        }
238	    }
239	
240	    /**
241	     * Rejects creating an owner whose normalized telephone is already used by another owner, with
242	     * 409 Conflict.
243	     *
244	     * @param owner the owner being created
245	     */
246	    private void rejectWhenTelephoneInUse(Owner owner) {
247	        String normalizedTelephone = owner.getTelephone();
248	        if (isTelephoneInUse(normalizedTelephone)) {
249	            throw new DuplicateTelephoneException(
250	                "An owner with telephone " + normalizedTelephone + " already exists");
251	        }
252	    }
253	
254	    /**
255	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
256	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
257	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
258	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
259	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
260	     * server's current date. Canonicalising the address here, before the household checks read it,
261	     * ensures duplicate detection and the shared household id both compare the normalized form.
262	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
263	     * duplicate, household and customer-code rules.
264	     *
265	     * @param owner the newly mapped owner to canonicalize
266	     */
267	    private void normalizeOwnerFields(Owner owner) {
268	        // Normalize the address on create so it is stored and returned in canonical form and every
269	        // later comparison (household duplicate detection and the shared household id) uses it.
270	        // A value that is blank after normalization is rejected with 400.
271	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
272	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
273	        // A value that cannot form a valid E.164 number is rejected with 400.
274	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
275	        // Store the (already syntactically validated) email lower-cased so it is persisted and
276	        // returned in canonical form. A missing email is left untouched.
277	        owner.setEmail(normalizeEmail(owner.getEmail()));
278	        // Default the registration date to the server's current date when the client did not
279	        // supply one, then roll the effective date forward to a business day so a Saturday or
280	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
281	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
282	        // date-derived field (such as the membership number's year segment) and the per-day
283	        // create-limit are computed from.
284	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
285	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
286	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
287	    }
288	
289	    /**
290	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
291	     * following Monday, while a weekday is returned unchanged. Applied to the effective
292	     * registration date (whether supplied in the request or defaulted to the server date) so the
293	     * persisted registration date, every value derived from it and the per-day create-limit all
294	     * use the adjusted business day.
295	     *
296	     * @param date the effective registration date
297	     * @return the same date if it is a weekday, otherwise the following Monday
298	     */
299	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
300	        java.time.LocalDate adjusted = date;
301	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
302	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
303	            adjusted = adjusted.plusDays(1);
304	        }
305	        return adjusted;
306	    }
307	
308	    /**
309	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
310	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
311	     * syntactically valid address (rejecting anything else with 400).
312	     *
313	     * @param email the email value (may be {@code null})
314	     * @return the lower-cased email, or {@code null} if the input was {@code null}
315	     */
316	    private String normalizeEmail(String email) {
317	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
318	    }
319	
320	    /**
321	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
322	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
323	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
324	     * the owners already in that city (e.g. 'LON-SMI-0007').
325	     *
326	     * @param city     the owner's city
327	     * @param lastName the owner's last name
328	     * @return the formatted customer code
329	     */
330	    private String nextCustomerCode(String city, String lastName) {
331	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
332	            .toUpperCase(java.util.Locale.ROOT);
333	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
334	            .toUpperCase(java.util.Locale.ROOT);
335	        int sequence = countOwnersInCity(city) + 1;
336	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
337	    }
338	
339	    /**
340	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
341	     * fix the per-city sequence of an owner's customer code at creation time.
342	     *
343	     * @param city the city of the owner being created
344	     * @return the number of existing owners in a matching city
345	     */
346	    private int countOwnersInCity(String city) {
347	        return (int) this.clinicService.findAllOwners().stream()
348	            .filter(existing -> existing.getCity() != null
349	                && existing.getCity().equalsIgnoreCase(city))
350	            .count();
351	    }
352	
353	    /**
354	     * Counts the existing owners whose registration date is the given adjusted business day. Used
355	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
356	     * owners already carry that business day as their registration date.
357	     *
358	     * @param date the adjusted business-day registration date to match
359	     * @return the number of existing owners registered on that date
360	     */
361	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
362	        return (int) this.clinicService.findAllOwners().stream()
363	            .filter(existing -> date.equals(existing.getRegistrationDate()))
364	            .count();
365	    }
366	
367	    /**
368	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
369	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
370	     *
371	     * @param customerCode     the owner's customer code
372	     * @param registrationDate the owner's registration date
373	     * @return the formatted membership number
374	     */
375	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
376	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
377	    }
378	
379	    /**
380	     * Determines whether the given normalized telephone is already used by an existing owner.
381	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
382	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
383	     * as the same number.
384	     *
385	     * @param normalizedTelephone the normalized (E.164) telephone to look for
386	     * @return {@code true} if another owner already uses this telephone
387	     */
388	    private boolean isTelephoneInUse(String normalizedTelephone) {
389	        return isValueInUseByExistingOwner(Owner::getTelephone, telephoneNormalizer::normalize,
390	            normalizedTelephone);
391	    }
392	
393	    /**
394	     * Determines whether the given already-normalized value is used by an existing owner for the
395	     * field read by {@code accessor}, comparing each existing owner's value in the same normalized
396	     * form produced by {@code normalizer}. Shared by the create-time uniqueness rules so each rule
397	     * only supplies the field to read and how to normalize it.
398	     *
399	     * @param accessor        reads the field to compare from an existing owner
400	     * @param normalizer      canonicalizes an existing owner's value into the same form as
401	     *                        {@code normalizedValue}
402	     * @param normalizedValue the already-normalized value to look for
403	     * @return {@code true} if an existing owner already uses this value
404	     */
405	    private boolean isValueInUseByExistingOwner(java.util.function.Function<Owner, String> accessor,
406	                                                java.util.function.UnaryOperator<String> normalizer,
407	                                                String normalizedValue) {
408	        if (normalizedValue == null) {
409	            return false;
410	        }
411	        return this.clinicService.findAllOwners().stream()
412	            .map(accessor)
413	            .map(normalizer)
414	            .anyMatch(normalizedValue::equals);
415	    }
416	
417	    /**
418	     * Returns the existing owners who share the given household, i.e. have the same last name and
419	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
420	     * differing only in letter case or in incidental whitespace are treated as the same household.
421	     *
422	     * @param lastName the last name of the owner being created
423	     * @param address  the address of the owner being created
424	     * @return the existing owners with a matching last name and address (possibly empty)
425	     */
426	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
427	        String householdKey = householdNormalizer.householdKey(lastName, address);
428	        return this.clinicService.findAllOwners().stream()
429	            .filter(existing -> householdNormalizer
430	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
431	            .toList();
432	    }
433	
434	    /**
435	     * Counts the existing owners who share the given first and last name, compared
436	     * case-insensitively. Used to fix an owner's namesake count at creation time.
437	     *
438	     * @param firstName the first name of the owner being created
439	     * @param lastName  the last name of the owner being created
440	     * @return the number of existing owners with a matching first and last name
441	     */
442	    private int countNamesakes(String firstName, String lastName) {
443	        return (int) this.clinicService.findAllOwners().stream()
444	            .filter(existing -> existing.getFirstName() != null
445	                && existing.getFirstName().equalsIgnoreCase(firstName)
446	                && existing.getLastName() != null
447	                && existing.getLastName().equalsIgnoreCase(lastName))
448	            .count();
449	    }
450	
451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Override
453	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
454	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
455	        if (currentOwner == null) {
456	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
457	        }
458	        currentOwner.setAddress(ownerFieldsDto.getAddress());
459	        currentOwner.setCity(ownerFieldsDto.getCity());
460	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
461	        currentOwner.setLastName(ownerFieldsDto.getLastName());
462	        // Normalize the telephone to canonical E.164 form so it is stored and returned
463	        // consistently with create; an unformattable value is rejected with 400.
464	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
465	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
466	        this.clinicService.saveOwner(currentOwner);
467	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
468	    }
469	
470	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
471	    @Transactional
472	    @Override
473	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
474	        Owner owner = this.clinicService.findOwnerById(ownerId);
475	        if (owner == null) {
476	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
477	        }
478	        this.clinicService.deleteOwner(owner);
479	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
480	    }
481	
482	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
483	    @Override
484	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
485	        Owner owner = this.clinicService.findOwnerById(ownerId);
486	        if (owner == null) {
487	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
488	        }
489	        HttpHeaders headers = new HttpHeaders();
490	        Pet pet = petMapper.toPet(petFieldsDto);
491	        owner.setId(ownerId);
492	        pet.setOwner(owner);
493	        pet.getType().setName(null);
494	        this.clinicService.savePet(pet);
495	        PetDto petDto = petMapper.toPetDto(pet);
496	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
497	            .buildAndExpand(pet.getId()).toUri());
498	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
499	    }
500	
501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
504	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
505	        if (currentOwner != null) {
506	            Pet currentPet = this.clinicService.findPetById(petId);
507	            if (currentPet != null) {
508	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
509	                currentPet.setName(petFieldsDto.getName());
510	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
511	                this.clinicService.savePet(currentPet);
512	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
513	            }
514	        }
515	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
516	    }
517	
518	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
519	    @Override
520	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
521	        HttpHeaders headers = new HttpHeaders();
522	        Visit visit = visitMapper.toVisit(visitFieldsDto);
523	        Pet pet = new Pet();
524	        pet.setId(petId);
525	        visit.setPet(pet);
526	        this.clinicService.saveVisit(visit);
527	        VisitDto visitDto = visitMapper.toVisitDto(visit);
528	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
529	            .buildAndExpand(visit.getId()).toUri());
530	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
531	    }
532	
533	
534	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
535	    @Override
536	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
537	        Owner owner = this.clinicService.findOwnerById(ownerId);
538	        if (owner != null) {
539	            Pet pet = owner.getPet(petId);
540	            if (pet != null) {
541	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
542	            }
543	        }
544	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
545	    }
546	}
