 * 409 Conflict.
 *
 * @param owner the owner being created
 */
private void rejectWhenEmailInUse(Owner owner) {
    String normalizedEmail = owner.getEmail();
    if (isValueInUseByExistingOwner(Owner::getEmail, this::normalizeEmail, normalizedEmail)) {
